<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';$pdo=db();$action=(string)($_POST['action']??$_GET['action']??'');if($action==='download'){require_permission('projects.view');$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM project_files WHERE id=?');$q->execute([$id]);$f=$q->fetch();if(!$f){http_response_code(404);exit('Archivo no encontrado.');}$path=__DIR__.'/'.ltrim((string)$f['file_path'],'/');if(!is_file($path)){http_response_code(404);exit('Archivo no disponible.');}header('Content-Type: '.(string)$f['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.str_replace('"','',(string)$f['file_name']).'"');readfile($path);exit;}require_permission('projects.manage');verify_csrf();$projectId=(int)($_POST['project_id']??0);pm_fetch_project($pdo,$projectId);if($action==='upload'){try{$file=crm_upload_document($_FILES['file']??[],'project-'.$projectId,20);if($file){$pdo->prepare('INSERT INTO project_files(project_id,file_name,file_path,mime_type,file_size,uploaded_by) VALUES (?,?,?,?,?,?)')->execute([$projectId,$file['file_name'],$file['file_path'],$file['mime_type'],$file['file_size'],(int)$_SESSION['user_id']]);flash('success','Archivo cargado.');}}catch(Throwable $e){flash('error',$e->getMessage());}}elseif($action==='delete'){$id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT file_path FROM project_files WHERE id=? AND project_id=?');$q->execute([$id,$projectId]);$path=$q->fetchColumn();if($path){@unlink(__DIR__.'/'.ltrim((string)$path,'/'));$pdo->prepare('DELETE FROM project_files WHERE id=? AND project_id=?')->execute([$id,$projectId]);flash('success','Archivo eliminado.');}}redirect('project_view.php?id='.$projectId);
